//mapa-turystyczna.pl/route/iv1r","elevation_gain_verified_at":"2026-11-24T00:00:00Z","time_source_url":"https://mapa-turystyczna.pl/route/iv1r","time_verified_at":"2026-11-24T00:00:00Z","i18n":{"pl":{"name":"Wysoki Kamie\u0144: czerwonym ze Szklarskiej Por\u0119by","description":"Ze stacji Szklarska Por\u0119ba G\u00f3rna przez osiedle Podg\u00f3rze i Rozdro\u017ce pod Wysokim Kamieniem do punktu szlakowego Wysoki Kamie\u0144. Czerwony szlak, ko\u0144cowo wsp\u00f3lny z \u017c\u00f3\u0142tym. 3,2 km, 413 m podej\u015b\u0107 i 1 godz. 31 min dotycz\u0105 wej\u015bcia; powr\u00f3t jest poza zakresem.","notes":"Pocz\u0105tek \u015bladu jest przy stacji, a nie w dowolnym punkcie miasta. Nie dodano odcinka do pinezki szczytu. Przed wyj\u015bciem sprawd\u017a pogod\u0119 i komunikaty o pracach le\u015bnych; GPX nie potwierdza otwarcia ani bezpiecze\u0144stwa."},"en":{"name":"Wysoki Kamie\u0144: red trail from Szklarska Por\u0119ba","description":"From Szklarska Por\u0119ba G\u00f3rna station via the Podg\u00f3rze estate and Rozdro\u017ce pod Wysokim Kamieniem to the Wysoki Kamie\u0144 trail point. Follow red markings, shared with yellow at the end. The 3.2 km, 413 m ascent and 1 h 31 min exclude the return.","notes":"The track starts at the station, not at an arbitrary point in town. No connector to the peak pin is added. Check weather and forestry notices before setting off; GPX does not confirm access or safety."},"ua":{"name":"Wysoki Kamie\u0144: \u0447\u0435\u0440\u0432\u043e\u043d\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u043c \u0437\u0456 Szklarska Por\u0119ba","description":"\u0412\u0456\u0434 \u0441\u0442\u0430\u043d\u0446\u0456\u0457 Szklarska Por\u0119ba G\u00f3rna \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0439\u043e\u043d Podg\u00f3rze \u0442\u0430 Rozdro\u017ce pod Wysokim Kamieniem \u0434\u043e \u0442\u043e\u0447\u043a\u0438 Wysoki Kamie\u0144 \u043d\u0430 \u0441\u0442\u0435\u0436\u0446\u0456. \u0427\u0435\u0440\u0432\u043e\u043d\u0435 \u043c\u0430\u0440\u043a\u0443\u0432\u0430\u043d\u043d\u044f, \u043d\u0430\u043f\u0440\u0438\u043a\u0456\u043d\u0446\u0456 \u0441\u043f\u0456\u043b\u044c\u043d\u0435 \u0437 \u0436\u043e\u0432\u0442\u0438\u043c. 3,2 \u043a\u043c, 413 \u043c \u043d\u0430\u0431\u043e\u0440\u0443 \u0432\u0438\u0441\u043e\u0442\u0438 \u0442\u0430 1 \u0433\u043e\u0434 31 \u0445\u0432 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f.","notes":"\u0422\u0440\u0435\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0431\u0456\u043b\u044f \u0441\u0442\u0430\u043d\u0446\u0456\u0457, \u0430 \u043d\u0435 \u0432 \u0434\u043e\u0432\u0456\u043b\u044c\u043d\u0456\u0439 \u0442\u043e\u0447\u0446\u0456 \u043c\u0456\u0441\u0442\u0430. \u0417\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0437 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u043e\u044e \u0432\u0435\u0440\u0448\u0438\u043d\u0438 \u043d\u0435 \u0434\u043e\u0434\u0430\u043d\u043e. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0433\u043e\u0434\u0443 \u0439 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043f\u0440\u043e \u043b\u0456\u0441\u043e\u0432\u0456 \u0440\u043e\u0431\u043e\u0442\u0438; GPX \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0434\u043e\u0441\u0442\u0443\u043f\u0443 \u0447\u0438 \u0431\u0435\u0437\u043f\u0435\u043a\u0438."},"zh":{"name":"Wysoki Kamie\u0144\uff1a\u4eceSzklarska Por\u0119ba\u6cbf\u7ea2\u8272\u6b65\u9053\u4e0a\u5c71","description":"\u4eceSzklarska Por\u0119ba G\u00f3rna\u8f66\u7ad9\u7ecfPodg\u00f3rze\u5c45\u6c11\u533a\u53caRozdro\u017ce pod Wysokim Kamieniem\u524d\u5f80Wysoki Kamie\u0144\u6b65\u9053\u70b9\u3002\u6cbf\u7ea2\u8272\u6807\u8bb0\u884c\u8d70\uff0c\u672b\u6bb5\u4e0e\u9ec4\u8272\u6b65\u9053\u5171\u7ebf\u30023.2\u516c\u91cc\u3001\u7d2f\u8ba1\u722c\u5347413\u7c73\u53ca1\u5c0f\u65f631\u5206\u949f\u4e0d\u542b\u8fd4\u7a0b\u3002","notes":"\u8f68\u8ff9\u4ece\u8f66\u7ad9\u5f00\u59cb\uff0c\u5e76\u975e\u57ce\u9547\u4e2d\u7684\u4efb\u610f\u4f4d\u7f6e\u3002\u672a\u6dfb\u52a0\u901a\u5f80\u5c71\u5cf0\u6807\u8bb0\u7684\u8fde\u63a5\u7ebf\u3002\u51fa\u53d1\u524d\u8bf7\u6838\u5b9e\u5929\u6c14\u53ca\u6797\u4e1a\u4f5c\u4e1a\u516c\u544a\uff1bGPX\u4e0d\u786e\u8ba4\u8def\u7ebf\u5f00\u653e\u6216\u5b89\u5168\u3002"}}}},{"kind":"poi","body":{"peak_slug":"stog-izerski","type_slug":"shelter","trail_id":null,"latitude":50.892497,"longitude":15.308775,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/2037-dolnoslaskie-schronisko-na-stogu-izerskim","last_verified_at":"2026-11-24T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps?q=50.892497,15.308775","i18n":{"pl":{"name":"Schronisko na Stogu Izerskim","description":"Schronisko na zboczu Stogu Izerskiego, przy wybranym czerwonym szlaku przed jego ko\u0144cowym podej\u015bciem. PTTK opisuje budynek z lat 1922\u20131924 i widoki w stron\u0119 \u015awieradowa-Zdroju.","tips":"Przed wizyt\u0105 potwierd\u017a godziny, dost\u0119pne us\u0142ugi i ewentualny nocleg u gospodarza. Wpis nie potwierdza dost\u0119pno\u015bci miejsc ani dzia\u0142ania kolei gondolowej."},"en":{"name":"Schronisko na Stogu Izerskim \u2014 mountain hut","description":"Mountain hut on the slope of St\u00f3g Izerski, beside the selected red trail before its final ascent. PTTK describes the 1922\u20131924 building and views towards \u015awierad\u00f3w-Zdr\u00f3j.","tips":"Confirm opening hours, services and any overnight stay with the operator before visiting. This entry does not confirm vacancies or gondola operation."},"ua":{"name":"Schronisko na Stogu Izerskim \u2014 \u0433\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a","description":"\u0413\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u043d\u0430 \u0441\u0445\u0438\u043b\u0456 St\u00f3g Izerski \u0431\u0456\u043b\u044f \u043e\u0431\u0440\u0430\u043d\u043e\u0433\u043e \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u043b\u044c\u043d\u0438\u043c \u043f\u0456\u0434\u0439\u043e\u043c\u043e\u043c. PTTK \u043e\u043f\u0438\u0441\u0443\u0454 \u0431\u0443\u0434\u0456\u0432\u043b\u044e 1922\u20131924 \u0440\u043e\u043a\u0456\u0432 \u0456 \u043a\u0440\u0430\u0454\u0432\u0438\u0434\u0438 \u0432 \u0431\u0456\u043a \u015awierad\u00f3w-Zdr\u00f3j.","tips":"\u041f\u0435\u0440\u0435\u0434 \u0432\u0456\u0437\u0438\u0442\u043e\u043c \u0443\u0442\u043e\u0447\u043d\u0456\u0442\u044c \u0443 \u0433\u043e\u0441\u043f\u043e\u0434\u0430\u0440\u044f \u0433\u043e\u0434\u0438\u043d\u0438 \u0440\u043e\u0431\u043e\u0442\u0438, \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0439 \u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u043d\u043e\u0447\u0456\u0432\u043b\u0456. \u0417\u0430\u043f\u0438\u0441 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0432\u0456\u043b\u044c\u043d\u0438\u0445 \u043c\u0456\u0441\u0446\u044c \u0447\u0438 \u0440\u043e\u0431\u043e\u0442\u0438 \u0433\u043e\u043d\u0434\u043e\u043b\u044c\u043d\u043e\u0457 \u0434\u043e\u0440\u043e\u0433\u0438."},"zh":{"name":"Schronisko na Stogu Izerskim\u2014\u2014\u5c71\u5c4b","description":"\u4f4d\u4e8eSt\u00f3g Izerski\u5c71\u5761\u4e0a\uff0c\u9760\u8fd1\u6240\u9009\u7ea2\u8272\u6b65\u9053\u7684\u6700\u540e\u4e0a\u5761\u6bb5\u4e4b\u524d\u3002PTTK\u4ecb\u7ecd\u4e86\u8fd9\u5ea7\u5efa\u4e8e1922\u81f31924\u5e74\u7684\u5efa\u7b51\u53ca\u671d\u5411\u015awierad\u00f3w-Zdr\u00f3j\u7684\u666f\u89c2\u3002","tips":"\u5230\u8bbf\u524d\u8bf7\u5411\u7ecf\u8425\u8005\u786e\u8ba4\u5f00\u653e\u65f6\u95f4\u3001\u670d\u52a1\u53ca\u4f4f\u5bbf\u5b89\u6392\u3002\u672c\u6761\u76ee\u4e0d\u786e\u8ba4\u7a7a\u623f\u6216\u7f06\u8f66\u8fd0\u884c\u60c5\u51b5\u3002"}}}},{"kind":"poi","body":{"peak_slug":"wysoki-kamien","type_slug":"shelter","trail_id":null,"latitude":50.845549,"longitude":15.491588,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/2033-dolnoslaskie-wysoki-kamien-schronisko","last_verified_at":"2026-11-24T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps?q=50.845549,15.491588","i18n":{"pl":{"name":"Wysoki Kamie\u0144 \u2014 rejon schroniska i ska\u0142","description":"Rejon prywatnego schroniska przy ska\u0142ach Wysokiego Kamienia, opisany w katalogu PTTK. Punkt orientacyjny le\u017cy przy ko\u0144cu wybranego podej\u015bcia ze Szklarskiej Por\u0119by.","tips":"Pozycja oznacza rejon obiektu, nie jego wej\u015bcie. Potwierd\u017a aktualne godziny i us\u0142ugi przed wizyt\u0105; nie potwierdzono nocleg\u00f3w, cen ani dost\u0119pu do wie\u017cy."},"en":{"name":"Wysoki Kamie\u0144 \u2014 hut and rocks area","description":"Area of the private hut beside the rocks of Wysoki Kamie\u0144, described in the PTTK catalogue. This landmark is near the end of the selected ascent from Szklarska Por\u0119ba.","tips":"The position marks the facility area, not its entrance. Confirm current hours and services before visiting; accommodation, prices and tower access are unverified."},"ua":{"name":"Wysoki Kamie\u0144 \u2014 \u0440\u0430\u0439\u043e\u043d \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u0442\u0430 \u0441\u043a\u0435\u043b\u044c","description":"\u0420\u0430\u0439\u043e\u043d \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u0431\u0456\u043b\u044f \u0441\u043a\u0435\u043b\u044c Wysoki Kamie\u0144, \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0439 \u0443 \u043a\u0430\u0442\u0430\u043b\u043e\u0437\u0456 PTTK. \u041e\u0440\u0456\u0454\u043d\u0442\u0438\u0440 \u0440\u043e\u0437\u0442\u0430\u0448\u043e\u0432\u0430\u043d\u0438\u0439 \u0431\u0456\u043b\u044f \u043a\u0456\u043d\u0446\u044f \u043e\u0431\u0440\u0430\u043d\u043e\u0433\u043e \u043f\u0456\u0434\u0439\u043e\u043c\u0443 \u0437\u0456 Szklarska Por\u0119ba.","tips":"\u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u0432\u043a\u0430\u0437\u0443\u0454 \u0440\u0430\u0439\u043e\u043d \u043e\u0431\u2019\u0454\u043a\u0442\u0430, \u0430 \u043d\u0435 \u0439\u043e\u0433\u043e \u0432\u0445\u0456\u0434. \u041f\u0435\u0440\u0435\u0434 \u0432\u0456\u0437\u0438\u0442\u043e\u043c \u0443\u0442\u043e\u0447\u043d\u0456\u0442\u044c \u0433\u043e\u0434\u0438\u043d\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0438; \u043d\u043e\u0447\u0456\u0432\u043b\u044f, \u0446\u0456\u043d\u0438 \u0442\u0430 \u0434\u043e\u0441\u0442\u0443\u043f \u0434\u043e \u0432\u0435\u0436\u0456 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0456."},"zh":{"name":"Wysoki Kamie\u0144\u2014\u2014\u5c71\u5c4b\u53ca\u5ca9\u77f3\u533a\u57df","description":"PTTK\u76ee\u5f55\u4ecb\u7ecd\u7684Wysoki Kamie\u0144\u5ca9\u77f3\u65c1\u79c1\u4eba\u5c71\u5c4b\u533a\u57df\u3002\u6b64\u5730\u6807\u4f4d\u4e8e\u6240\u9009Szklarska Por\u0119ba\u4e0a\u5c71\u8def\u7ebf\u7684\u7ec8\u70b9\u9644\u8fd1\u3002","tips":"\u6807\u8bb0\u8868\u793a\u8bbe\u65bd\u6240\u5728\u533a\u57df\uff0c\u5e76\u975e\u5165\u53e3\u3002\u5230\u8bbf\u524d\u8bf7\u786e\u8ba4\u6700\u65b0\u5f00\u653e\u65f6\u95f4\u548c\u670d\u52a1\uff1b\u4f4f\u5bbf\u3001\u4ef7\u683c\u53ca\u89c2\u666f\u5854\u901a\u884c\u60c5\u51b5\u672a\u7ecf\u6838\u5b9e\u3002"}}}}],"ranges":[{"id":3,"slug":"gory-izerskie"}]}$manifest$::jsonb;
 manifest_hash text='965419a3686a78ee31b4f26a3cd5d4f535856646e0a4558a12a08a7c90213e14';
 receipt jsonb; identity jsonb; entry jsonb; body jsonb; actual jsonb; projected jsonb; expected jsonb;
 records jsonb='[]'; peak bigint; saved_id bigint; tr_lang text; tr jsonb;
 trail public.trails%rowtype; poi public.pois%rowtype; target regclass; reference record; linked boolean;
begin
 perform pg_advisory_xact_lock(251122,4);
 if to_regprocedure('public.admin_save_trail(bigint,jsonb,timestamptz)') is null then raise exception 'Apply catalogue migration 014 first'; end if;
 select snapshot into receipt from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-05' for update;

 for identity in select value from jsonb_array_elements(manifest->'peaks') loop
  select to_jsonb(p) into actual from public.peaks p where id=(identity->>'id')::bigint for update;
  if actual is null then raise exception 'Reviewed peak missing: %',identity->>'slug'; end if;
  select jsonb_object_agg(k,actual->k) into projected from jsonb_object_keys(identity) k;
  expected=identity;
  if projected is distinct from expected then raise exception 'Reviewed peak identity changed: %',identity->>'slug'; end if;
 end loop;
 for identity in select value from jsonb_array_elements(manifest->'ranges') loop
  if not exists(select from public.mountain_ranges where id=(identity->>'id')::bigint and slug=identity->>'slug') then raise exception 'Reviewed range changed'; end if;
 end loop;
 if receipt is not null then

 if receipt->>'manifest_sha256' is distinct from manifest_hash or receipt->>'version' is distinct from '1'
    or jsonb_typeof(receipt->'records') is distinct from 'array' or jsonb_array_length(receipt->'records')<>4
    or (select count(distinct (e->>'kind',e->>'id')) from jsonb_array_elements(receipt->'records') e)<>4
    or (select count(distinct (e->>'kind',e->>'peak_id')) from jsonb_array_elements(receipt->'records') e)<>4
 then raise exception 'Incomplete or different non-KGP receipt'; end if;
 for entry in select value from jsonb_array_elements(receipt->'records') loop
  if entry->>'kind' is null or entry->>'kind' not in ('trail','poi') or not exists(select from jsonb_array_elements(manifest->'peaks') p where p->>'id'=entry->>'peak_id') then raise exception 'Unexpected receipt identity'; end if;
  saved_id=(entry->>'id')::bigint;

 if entry->>'kind'='trail' then
  perform 1 from public.trails where id=saved_id for update;
  perform 1 from public.trails_i18n where trail_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(t),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.trails_i18n i where i.trail_id=t.id),'[]')) into actual from public.trails t where t.id=saved_id;
 else
  perform 1 from public.pois where id=saved_id for update;
  perform 1 from public.pois_i18n where poi_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(p),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.pois_i18n i where i.poi_id=p.id),'[]')) into actual from public.pois p where p.id=saved_id;
 end if;

  if actual is distinct from entry->'snapshot' then raise exception 'Imported record changed: % %',entry->>'kind',saved_id; end if;
 end loop;
 raise notice 'Non-KGP package already applied; unchanged'; return; end if;

 for identity in select value from jsonb_array_elements(manifest->'peaks') loop
  if exists(select from public.trails where peak_id=(identity->>'id')::bigint)
   or exists(select from public.pois where peak_id=(identity->>'id')::bigint) then raise exception 'Existing catalogue content; review required: %',identity->>'slug'; end if;
 end loop;
 for entry in select value from jsonb_array_elements(manifest->'records') loop
  body=entry->'body';
  select id into peak from public.peaks where slug=body->>'peak_slug' and active for update;
  if peak is null then raise exception 'Reviewed peak missing'; end if;
  body=body||jsonb_build_object('peak_id',peak);
  if entry->>'kind'='trail' then
   if exists(select from public.trails where slug=body->>'slug') then raise exception 'Trail slug already exists'; end if;
   trail=jsonb_populate_record(null::public.trails,body);
   insert into public.trails (peak_id,slug,start_point_name,end_point_name,distance_km,elevation_gain_m,time_min,difficulty,route_type,active,source_url,last_verified_at,map_url,gpx_url,distance_source_url,distance_verified_at,elevation_gain_source_url,elevation_gain_verified_at,time_source_url,time_verified_at,route_geometry,geometry_source_url,geometry_verified_at) values (trail.peak_id,trail.slug,trail.start_point_name,trail.end_point_name,trail.distance_km,trail.elevation_gain_m,trail.time_min,trail.difficulty,trail.route_type,trail.active,trail.source_url,trail.last_verified_at,trail.map_url,trail.gpx_url,trail.distance_source_url,trail.distance_verified_at,trail.elevation_gain_source_url,trail.elevation_gain_verified_at,trail.time_source_url,trail.time_verified_at,trail.route_geometry,trail.geometry_source_url,trail.geometry_verified_at) returning id into saved_id;
   for tr_lang,tr in select key,value from jsonb_each(body->'i18n') loop
    insert into public.trails_i18n(trail_id,lang,name,description,notes) values(saved_id,tr_lang,tr->>'name',tr->>'description',tr->>'notes'); end loop;

  else
   if (select count(*) from public.poi_types where slug=body->>'type_slug')<>1 then raise exception 'POI type missing or ambiguous'; end if;
   body=body||jsonb_build_object('type_id',(select id from public.poi_types where slug=body->>'type_slug'));
   poi=jsonb_populate_record(null::public.pois,body);
   insert into public.pois (peak_id,trail_id,type_id,latitude,longitude,active,source_url,last_verified_at,website_url,google_maps_url) values (poi.peak_id,poi.trail_id,poi.type_id,poi.latitude,poi.longitude,poi.active,poi.source_url,poi.last_verified_at,poi.website_url,poi.google_maps_url) returning id into saved_id;
   for tr_lang,tr in select key,value from jsonb_each(body->'i18n') loop
    insert into public.pois_i18n(poi_id,lang,name,description,tips) values(saved_id,tr_lang,tr->>'name',tr->>'description',tr->>'tips'); end loop;

  end if;

 if entry->>'kind'='trail' then
  perform 1 from public.trails where id=saved_id for update;
  perform 1 from public.trails_i18n where trail_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(t),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.trails_i18n i where i.trail_id=t.id),'[]')) into actual from public.trails t where t.id=saved_id;
 else
  perform 1 from public.pois where id=saved_id for update;
  perform 1 from public.pois_i18n where poi_id=saved_id order by lang collate "C" for update;
  select jsonb_build_object('row',to_jsonb(p),'i18n',coalesce((select jsonb_agg(to_jsonb(i) order by i.lang collate "C") from public.pois_i18n i where i.poi_id=p.id),'[]')) into actual from public.pois p where p.id=saved_id;
 end if;

  records=records||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','id',saved_id,'peak_id',peak,'snapshot',actual));
 end loop;
 insert into peakguide_private.catalogue_batch_receipts(batch_key,snapshot)values('nonkgp-05',jsonb_build_object('version',1,'manifest_sha256',manifest_hash,'records',records));
 raise notice 'Added four trails and four POIs in four languages; preserved all peak fields';
end $batch$;
-- Reviewed non-KGP data. Read README.md; keep a current backup. Project owner only.
-- ASCII-only SQL; Unicode is encoded inside JSON. No network calls.
set local lock_timeout='5s';
set local timezone='UTC';
create schema if not exists peakguide_private;
create table if not exists peakguide_private.catalogue_batch_receipts(batch_key text primary key,snapshot jsonb not null,created_at timestamptz not null default now());
alter table peakguide_private.catalogue_batch_receipts enable row level security;
revoke all on peakguide_private.catalogue_batch_receipts from public,anon,authenticated;
do $batch$
